# --------------------------------------------------------------------------
# host side
# --------------------------------------------------------------------------
def _block_for(dtype, itemsize):
    # bfloat16 keeps the smaller tile: its compare is promoted to fp32, which
    # already reserves ~148 KB of UB at BLOCK 8192.
    if dtype is torch.bfloat16:
        return 8192
    if itemsize == 2:
        return 16384
    if itemsize == 4:
        return 8192
    if itemsize == 1:
        return 16384
    return 4096


def _pick_block(dtype, itemsize, n):
    block = _block_for(dtype, itemsize)
    if n < block:
        block = max(1024, triton.next_power_of_2(n))
    if n <= 8192:
        # Small inputs otherwise run as a single block on one core; four tiles
        # let four cores share the fixed per-block work.
        block = max(256, triton.next_power_of_2(n) >> 2)
    return block


def _flat_launch(a, b, out, n):
    block = _pick_block(a.dtype, a.element_size(), n)
    grid = (triton.cdiv(n, block),) if n else (1,)
    o = out.view(torch.int8)
    if n > _INT32_MAX:
        _ne_tensor_kernel_i64[grid](a, b, o, n, BLOCK=block)
    elif n and not (n & (block - 1)):
        _ne_tensor_kernel_aligned[(n // block,)](a, b, o, BLOCK=block)
    else:
        _ne_tensor_kernel[grid](a, b, o, n, BLOCK=block)


def _flat_scalar_launch(a, out, s, n):
    block = _pick_block(a.dtype, a.element_size(), n)
    grid = (triton.cdiv(n, block),) if n else (1,)
    o = out.view(torch.int8)
    if n > _INT32_MAX:
        _ne_scalar_kernel_i64[grid](a, o, s, n, BLOCK=block)
    else:
        _ne_scalar_kernel[grid](a, o, s, n, BLOCK=block)


def _bcast_args(shape, sa, sb):
    dims = list(shape)[::-1]
    asts = list(sa)[::-1]
    bsts = list(sb)[::-1]
    rank = len(dims)
    pad = _MAX_RANK - rank
    dims = dims + [1] * pad
    asts = asts + [0] * pad
    bsts = bsts + [0] * pad
    return rank, dims, asts, bsts


def _launch_bcast(a, b, out, shape, n):
    rank, dims, asts, bsts = _bcast_args(shape, a.stride(), b.stride())
    block = 2048
    grid = (triton.cdiv(n, block),) if n else (1,)
    _ne_bcast_kernel[grid](
        a,
        b,
        out.view(torch.int8),
        n,
        dims[0],
        dims[1],
        dims[2],
        dims[3],
        dims[4],
        dims[5],
        dims[6],
        dims[7],
        asts[0],
        asts[1],
        asts[2],
        asts[3],
        asts[4],
        asts[5],
        asts[6],
        asts[7],
        bsts[0],
        bsts[1],
        bsts[2],
        bsts[3],
        bsts[4],
        bsts[5],
        bsts[6],
        bsts[7],
        BLOCK=block,
        RANK=rank,
    )


def _launch_bcast_scalar(a, out, s, shape, n):
    rank, dims, asts, _ = _bcast_args(shape, a.stride(), (0,) * len(shape))
    block = 2048
    grid = (triton.cdiv(n, block),) if n else (1,)
    _ne_bcast_scalar_kernel[grid](
        a,
        out.view(torch.int8),
        s,
        n,
        dims[0],
        dims[1],
        dims[2],
        dims[3],
        dims[4],
        dims[5],
        dims[6],
        dims[7],
        asts[0],
        asts[1],
        asts[2],
        asts[3],
        asts[4],
        asts[5],
        asts[6],
        asts[7],
        BLOCK=block,
        RANK=rank,
    )


def not_equal(self, other):
    if not torch.is_tensor(other):
        n = self.numel()
        out = torch.empty_like(self, dtype=torch.bool)
        if self.is_contiguous():
            _flat_scalar_launch(self, out, other, n)
            return out
        _launch_bcast_scalar(self, out, other, self.shape, n)
        return out

    shape = self.shape
    if shape == other.shape and self.is_contiguous() and other.is_contiguous():
        n = self.numel()
        out = torch.empty_like(self, dtype=torch.bool)
        _flat_launch(self, other, out, n)
        return out

    bshape = torch.broadcast_shapes(tuple(shape), tuple(other.shape))
    while len(bshape) > _MAX_RANK and bshape[0] == 1:
        bshape = bshape[1:]
    a = self.expand(bshape)
    b = other.expand(bshape)
    n = 1
    for d in bshape:
        n *= d
    out = torch.empty(bshape, dtype=torch.bool, device=self.device)
    _launch_bcast(a, b, out, bshape, n)
    return out


